(() => {
'use strict';
const $=s=>document.querySelector(s), client=window.HVT, form=$('#editorForm');
let recoverAfterLogin=false;
let entries=[],editing=null,preview=false,pendingDelete=null,previewObject='',coverSequence=0;
const sections=window.HVTChapterAdmin;
const bodyEditor=window.HVTRich.mount($('#bodyRich'),{label:'Nội dung đọc'});
function chapterMode(){return form.elements.kind.value!=='video'&&form.elements.reading_mode.value==='sections'}
function showChapters(){const video=form.elements.kind.value==='video';$('#readingModeLabel').hidden=video;$('#readingModeHint').hidden=!chapterMode();$('#bodyCaption').textContent=chapterMode()?'Lời giới thiệu chung (không bắt buộc)':'Nội dung đọc';if(chapterMode())sections.attach(editing,preview);else sections.detach()}
function editItem(item){resetEditor();editing=item;for(const name of ['kind','title','author','description','body','url','cover_url','reading_mode'])form.elements[name].value=item[name]|| (name==='reading_mode'?'single':'');if(item.body_html)bodyEditor.setHTML(item.body_html);else bodyEditor.setText(item.body||'');$('#currentPdf').textContent=item.file_path?'Đã có PDF. Giữ nguyên nếu không chọn file mới hoặc đánh dấu xóa.':'';$('#editorTitle').textContent='Chỉnh sửa nội dung';$('#editorLabel').textContent=labels[item.kind];$('#saveItem').textContent='Lưu thông tin ↗';$('#cancelEdit').hidden=false;updateKind();showCover(client.cover(item))}
const labels={kinh:'KINH',sach:'SÁCH',video:'VIDEO'};
function message(text,error=false){const box=$('#message');box.hidden=!text;box.textContent=text;box.classList.toggle('error',error)}
function normalize(text){return String(text||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase()}
function showCover(src){if(previewObject&&previewObject!==src){URL.revokeObjectURL(previewObject);previewObject=''}$('#coverPreview').hidden=!src;$('#coverPlaceholder').hidden=!!src;if(src)$('#coverPreview').src=src;else $('#coverPreview').removeAttribute('src')}
$('#coverPreview').onerror=()=>{$('#coverPreview').hidden=true;$('#coverPlaceholder').hidden=false};
async function updateCover(){const seq=++coverSequence;const file=form.elements.coverFile.files[0];if(file){try{const blob=await client.imageFile(file);if(seq!==coverSequence)return;const object=URL.createObjectURL(blob);showCover(object);previewObject=object}catch(e){if(seq!==coverSequence)return;message(e.message,true);showCover('')}return}showCover(form.elements.removeCover.checked?'':client.https(form.elements.cover_url.value)?.href||client.cover(editing||{}))}
function updateKind(){const video=form.elements.kind.value==='video';$('#readingFields').hidden=video;$('#videoHelp').hidden=!video;form.elements.url.required=video;form.elements.url.placeholder=video?'https://www.youtube.com/watch?v=…':'https://…';updateVideo();showChapters()}
function updateVideo(){const value=form.elements.url.value.trim(),video=form.elements.kind.value==='video';$('#videoPreview').hidden=!video||!value;if(!video||!value)return;const id=client.youtubeId(value);$('#videoPreview').textContent=id?'✓ Liên kết YouTube hợp lệ · ID: '+id:client.embed(value)?'✓ Liên kết Vimeo hợp lệ':client.https(value)?'Liên kết ngoài: người xem có thể mở video tại trang nguồn.':'Liên kết phải là địa chỉ HTTPS hợp lệ.'}
function resetEditor(){coverSequence++;form.reset();bodyEditor.setHTML('');sections.detach();editing=null;showCover('');$('#currentPdf').textContent='';$('#editorTitle').textContent='Thêm nội dung';$('#editorLabel').textContent='GIEO MỘT TRANG MỚI';$('#saveItem').textContent='Đăng nội dung ↗';$('#saveItem').disabled=preview;$('#cancelEdit').hidden=true;updateKind()}
function render(){for(const [key,type] of [['All',null],['Kinh','kinh'],['Sach','sach'],['Video','video']])$('#count'+key).textContent=type?entries.filter(i=>i.kind===type).length:entries.length;const q=normalize($('#adminSearch').value),kind=$('#adminFilter').value;const list=entries.filter(i=>(kind==='all'||i.kind===kind)&&normalize(i.title+' '+i.author).includes(q));$('#resourceList').innerHTML=list.length?list.map(i=>`<div class="resource-row"><div class="resource-thumb">${client.cover(i)?`<img src="${client.esc(client.cover(i))}" alt="" loading="lazy">`:'❋'}</div><div><small>${labels[i.kind]}</small><h3>${client.esc(i.title)}</h3><div class="row-actions"><button class="text-link" data-edit="${client.esc(i.id)}">Chỉnh sửa</button><button class="text-link delete" data-delete="${client.esc(i.id)}">Xóa</button></div></div></div>`).join(''):`<p class="content-empty">${entries.length?'Không có kết quả phù hợp.':preview?'Nội dung thật sẽ xuất hiện sau khi kết nối Supabase.':'Chưa có nội dung. Hãy đăng trang đầu tiên.'}</p>`}
async function reload(){entries=await client.resources();render()}
function loggedOut(){window.HVTAdminTools.lock();entries=[];editing=null;$('#workspace').hidden=true;$('#loginSection').hidden=false;$('#loginForm').reset();resetEditor()}
window.addEventListener('hvt-auth-lost',()=>{recoverAfterLogin=true;window.HVTAdminTools.lock();$('#workspace').hidden=true;$('#loginSection').hidden=false;message('Phiên đăng nhập đã hết hạn. Nội dung đang soạn được giữ trong trang này. Đăng nhập lại để lưu; đừng tải lại trang khi chưa lưu.',true)});
$('#connectionBadge').textContent=client.configured?'Đã có cấu hình Supabase':'Chưa kết nối Supabase';$('#setupHelp').hidden=client.configured;$('#loginSubmit').disabled=!client.configured;if(client.unsafe)message('Chỉ dùng publishable key hoặc anon key trong config.js. Không đưa secret/service_role key lên website.',true);
$('#loginForm').onsubmit=async e=>{e.preventDefault();const btn=$('#loginSubmit');btn.disabled=true;message('Đang đăng nhập…');try{const f=new FormData(e.target),user=await client.signIn(f.get('email').trim(),f.get('password'));preview=false;window.HVTAdminTools.setSession({user,preview:false});$('#accountEmail').textContent=user.email;$('#loginSection').hidden=true;$('#workspace').hidden=false;$('#logout').hidden=false;$('#exitPreview').hidden=true;$('#demoBanner').hidden=true;e.target.reset();if(!recoverAfterLogin)resetEditor();recoverAfterLogin=false;await reload();message('Đăng nhập thành công. Bạn có thể đăng và quản lý nội dung.')}catch(error){message(error.message,true)}finally{btn.disabled=!client.configured}};
$('#logout').onclick=async()=>{if(!sections.canLeave())return;try{await client.signOut()}catch{}loggedOut();message('Đã đăng xuất.')};
$('#previewAdmin').onclick=()=>{preview=true;window.HVTAdminTools.setSession({preview:true});$('#accountEmail').textContent='Xem trước giao diện · chưa đăng nhập';$('#workspace').hidden=false;$('#loginSection').hidden=true;$('#demoBanner').hidden=false;$('#logout').hidden=true;$('#exitPreview').hidden=false;entries=[];resetEditor();render();message('')};$('#exitPreview').onclick=()=>{preview=false;loggedOut()};
$('#newItem').onclick=()=>{if(!sections.canLeave())return;resetEditor();$('#editorTitle').scrollIntoView({behavior:'smooth',block:'center'});form.elements.title.focus()};$('#cancelEdit').onclick=()=>{if(sections.canLeave())resetEditor()};$('#adminSearch').oninput=render;$('#adminFilter').onchange=render;$('#reloadItems').onclick=async()=>{if(preview){message('Kết nối Supabase để tải nội dung thật.');return}try{await reload();message('Đã làm mới danh sách.')}catch(e){message(e.message,true)}};
form.elements.kind.onchange=()=>{if(!sections.canLeave()){form.elements.kind.value=editing?.kind||'kinh';return}updateKind()};form.elements.reading_mode.onchange=()=>{if(!sections.canLeave()){form.elements.reading_mode.value='sections';return}showChapters()};form.elements.url.oninput=updateVideo;form.elements.coverFile.onchange=updateCover;form.elements.cover_url.oninput=updateCover;form.elements.removeCover.onchange=updateCover;
$('#resourceList').onclick=e=>{const edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');if(edit){const item=entries.find(i=>i.id===edit.dataset.edit);if(!item)return;if(!sections.canLeave())return;editItem(item);$('#editorTitle').scrollIntoView({behavior:'smooth',block:'center'})}if(del){pendingDelete=entries.find(i=>i.id===del.dataset.delete);$('#deleteName').textContent=pendingDelete?.title||'';$('#deleteDialog').showModal()}};
async function cleanup(files){const failures=[];for(const [bucket,path] of files){if(!path)continue;try{await client.removeFiles(bucket,[path])}catch{failures.push(bucket+'/'+path)}}return failures}
form.onsubmit=async e=>{e.preventDefault();if(preview||!client.hasSession()){message('Vui lòng kết nối Supabase và đăng nhập trước khi đăng nội dung.',true);return}form.elements.body.value=bodyEditor.getText();const body_html=bodyEditor.getHTML();const f=new FormData(form),kind=f.get('kind'),title=f.get('title').trim().normalize('NFC'),source=f.get('url').trim(),coverURL=f.get('cover_url').trim(),body=f.get('body').trim().normalize('NFC'),coverFile=f.get('coverFile'),pdfFile=f.get('pdfFile');let coverBlob=null;const added=[];let committed=false;const old=editing;$('#editorFields').disabled=true;bodyEditor.setDisabled(true);sections.setBusy(true);
try{if(!title)throw Error('Vui lòng nhập tiêu đề.');if(source&&!client.https(source))throw Error('Liên kết nguồn phải là HTTPS hợp lệ.');if(coverURL&&!client.https(coverURL))throw Error('Liên kết ảnh bìa phải là HTTPS hợp lệ.');if(kind==='video'&&!source)throw Error('Vui lòng dán liên kết video.');let pdf=kind==='video'||f.has('removePdf')?null:old?.file_path||null;let cover=f.has('removeCover')?null:old?.cover_path||null;let coverLink=f.has('removeCover')?'':coverURL;if(coverFile.size)coverBlob=await client.imageFile(coverFile);if(kind!=='video'&&pdfFile.size){if(pdfFile.size>20*1024*1024)throw Error('PDF tối đa 20 MB.');if(pdfFile.type!=='application/pdf'||await pdfFile.slice(0,5).text()!=='%PDF-')throw Error('Vui lòng chọn tập tin PDF hợp lệ.')}if(kind!=='video'&&!chapterMode()&&!source&&!body&&!pdf&&!pdfFile.size)throw Error('Cần nhập văn bản, tải PDF hoặc thêm liên kết nguồn.');$('#editorFields').disabled=true;message('Đang lưu nội dung…');if(coverBlob){cover=await client.upload('covers',coverBlob,'jpg');added.push(['covers',cover]);coverLink=''}else if(coverURL&&!f.has('removeCover'))cover=null;if(kind!=='video'&&pdfFile.size){pdf=await client.upload('documents',pdfFile,'pdf');added.push(['documents',pdf])}
const record={kind,title,reading_mode:chapterMode()?'sections':'single',body_html,author:f.get('author').trim().normalize('NFC'),description:f.get('description').trim().normalize('NFC'),body,url:source||null,file_path:pdf,cover_path:cover,cover_url:coverLink||null};const result=await client.api('/rest/v1/resources'+(old?'?id=eq.'+encodeURIComponent(old.id):''),{method:old?'PATCH':'POST',headers:{'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify(record)});if(!result?.length)throw Error('Không lưu được nội dung. Hãy kiểm tra quyền quản trị.');committed=true;const stale=[];if(old?.cover_path&&old.cover_path!==cover)stale.push(['covers',old.cover_path]);if(old?.file_path&&old.file_path!==pdf)stale.push(['documents',old.file_path]);const failures=await cleanup(stale);editing=result[0];$('#saveItem').textContent='Lưu thông tin ↗';$('#editorTitle').textContent='Chỉnh sửa nội dung';$('#cancelEdit').hidden=false;showChapters();try{await reload();message((old?'Đã cập nhật.':'Đã đăng nội dung.')+(chapterMode()?' Viết và lưu từng trang/phần ở bên dưới.':'')+(failures.length?' Cần xóa thủ công file cũ trong Storage: '+failures.join(', '):''),!!failures.length)}catch{message('Nội dung đã lưu. Chưa làm mới được danh sách; hãy nhấn Làm mới danh sách.',true)}}catch(error){const failures=!committed?await cleanup(added):[];message(error.message+(failures.length?' Cần dọn file chưa gắn bài trong Storage: '+failures.join(', '):''),true)}finally{$('#editorFields').disabled=false;bodyEditor.setDisabled(false);sections.setBusy(false);$('#saveItem').disabled=preview}};
$('#cancelDelete').onclick=()=>$('#deleteDialog').close();$('#confirmDelete').onclick=async()=>{if(!pendingDelete||!client.hasSession())return;const target=pendingDelete,btn=$('#confirmDelete');btn.disabled=true;try{const result=await client.api('/rest/v1/resources?id=eq.'+encodeURIComponent(target.id),{method:'DELETE',headers:{Prefer:'return=representation'}});if(!result?.length)throw Error('Bài không còn tồn tại hoặc tài khoản chưa có quyền xóa.');const failures=await cleanup([['covers',target.cover_path],['documents',target.file_path]]);$('#deleteDialog').close();if(editing?.id===target.id)resetEditor();entries=entries.filter(i=>i.id!==target.id);render();message('Đã xóa nội dung.'+(failures.length?' Cần dọn file trong Storage: '+failures.join(', '):''),!!failures.length)}catch(e){message(e.message,true);$('#deleteDialog').close()}finally{btn.disabled=false;pendingDelete=null}};
resetEditor();
})();
